SELECT 'gongkao', '余数与整除', 'kp-xc-quantity-math-operation-remainder-divisibility', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "余数与整除"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "余数与整除是数量关系的基础工具，整除判定规则和同余思想在很多题型中都有应用。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "整除判定：能被2整除看末位，被3整除看各位数字之和，被4整除看末两位，被8整除看末三位"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "能被9整除看各位数字之和，被11整除看奇数位与偶数位之差"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同余思想：a和b除以m余数相同，则(a-b)能被m整除"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "奇偶性：奇数±奇数=偶数，偶数±偶数=偶数，奇数±偶数=奇数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "余数性质：被除数 = 除数 × 商 + 余数，余数 < 除数"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "整除判定法：根据数字特征快速判断能否被某数整除"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同余法：多个数除以同一个数余数相同，利用差值的整除性"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "奇偶分析法：利用奇偶性排除不可能的选项"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "代入验证法：将选项代入条件验证是否满足整除或余数关系"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "整除判定规则记错，如被3整除和被9整除的规则搞混"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同余思想用错：应该是(a-b)能被m整除，不是(a+b)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略余数必须小于除数的约束"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "余数整除是基础工具题，单独出题不多但广泛应用。建议熟记整除判定规则和同余思想。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-余数与整除的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "余数与整除"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_remainder_divisibility", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
